import { useState } from "react";
import { cn } from "@/lib/utils";
import { logoUrlForDomain, storeMonogram } from "@/lib/store-logo";

export type StoreLogoProps = {
  name: string;
  domain: string | null;
  /** Optional precomputed value from the directory record; null forces fallback. */
  logoUrl?: string | null;
  loading?: "lazy" | "eager";
  className?: string;
};

/**
 * A fixed-size 120 × 64px logo surface. The CDN is never allowed to render
 * an autogenerated generic logo, and a missing asset becomes branded type.
 *
 * This component is staged for review. Do not apply to StoreTile yet.
 */
export function StoreLogo({
  name,
  domain,
  logoUrl,
  loading = "lazy",
  className,
}: StoreLogoProps) {
  const source = logoUrl === undefined ? logoUrlForDomain(domain) : logoUrl;
  const [failedSource, setFailedSource] = useState<string | null>(null);
  const useImage = Boolean(source && failedSource !== source);

  return (
    <span
      className={cn(
        "inline-flex h-16 w-[120px] shrink-0 items-center justify-center overflow-hidden rounded-[4px] bg-[#F9F8F6]",
        className,
      )}
    >
      {useImage ? (
        <img
          src={source!}
          alt={`${name} logo`}
          width={120}
          height={64}
          loading={loading}
          decoding="async"
          className="h-12 w-[112px] object-contain"
          onError={() => setFailedSource(source)}
        />
      ) : (
        <span
          role="img"
          aria-label={`${name} monogram`}
          className="flex h-full w-full items-center justify-center px-2 text-center font-display text-xl font-bold leading-tight text-[#A64B2A]"
        >
          {storeMonogram(name)}
        </span>
      )}
    </span>
  );
}
